package io.knowledgebrain.collaboration;
import java.util.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;
/** Current OWNER feedback/request metadata across one Study; independent of Course, no read-side mutations. */
final class StudyReviewQueueStore {
 static final Set<String> FILTERS=Set.of("ALL","NEEDS_FEEDBACK","HAS_FEEDBACK","RETRACTED_FEEDBACK","PENDING_RESUBMISSION","UNAVAILABLE");
 record Row(UUID submissionId,UUID authorId,long version,long assignmentVersion,String updatedAt,String feedbackStatus,Long feedbackVersion,Long feedbackSubmissionVersion,String retractionState,Long retractionVersion,boolean needsFeedback,Long requestVersion,String requestState,Long requestedSubmissionVersion,UUID assignmentId,String assignmentTitle,String assignmentState,String studyState) {}
 record Page(List<Row> items,UUID nextAfter) {}
 private final JdbcTemplate sql;private final StudyStore studies;
 StudyReviewQueueStore(DataSource ds,StudyStore studies){sql=new JdbcTemplate(ds);this.studies=studies;}
 Page list(UUID group,UUID space,UUID study,UUID after,int limit,String filter){
  for(var id:List.of(group,space,study))GroupInput.id(id.toString());if(after!=null)GroupInput.id(after.toString());if(limit<1||limit>100||filter==null||!FILTERS.contains(filter))throw GroupInput.bad();studies.get(group,space,study);
  String status="CASE WHEN g.feedback_id IS NULL THEN 'MISSING' WHEN g.submission_version>s.version OR (gr.retraction_id IS NOT NULL AND (gr.snapshot->>'state' IS NULL OR gr.snapshot->>'state' NOT IN ('RETRACTED','RESTORED'))) THEN 'UNAVAILABLE' WHEN g.submission_version<s.version THEN 'OUTDATED' WHEN gr.snapshot->>'state'='RETRACTED' THEN 'RETRACTED' ELSE 'CURRENT' END";
  String marker="CASE WHEN gr.retraction_id IS NULL THEN 'NONE' WHEN gr.snapshot->>'state' IN ('RETRACTED','RESTORED') THEN gr.snapshot->>'state' ELSE 'UNKNOWN' END";
  String request="CASE WHEN rr.request_id IS NULL THEN 'NONE' WHEN rr.snapshot->>'state'='REQUESTED' AND rr.submission_version=s.version AND rr.resolved_submission_version IS NULL THEN 'REQUESTED' WHEN rr.snapshot->>'state'='CANCELLED' AND rr.submission_version<=s.version AND rr.resolved_submission_version IS NULL THEN 'CANCELLED' WHEN rr.snapshot->>'state'='RESOLVED' AND rr.resolved_submission_version>rr.submission_version AND rr.resolved_submission_version<=s.version THEN 'RESOLVED' ELSE 'UNAVAILABLE' END";
  String condition=switch(filter){case "ALL"->"TRUE";case "NEEDS_FEEDBACK"->"feedback_status<>'CURRENT'";case "HAS_FEEDBACK"->"feedback_status='CURRENT'";case "RETRACTED_FEEDBACK"->"marker_state='RETRACTED' AND feedback_status<>'UNAVAILABLE'";case "PENDING_RESUBMISSION"->"request_state='REQUESTED'";case "UNAVAILABLE"->"feedback_status='UNAVAILABLE' OR request_state='UNAVAILABLE'";default->throw GroupInput.bad();};
  String query="WITH rows AS (SELECT s.submission_id,s.author_id,s.version,(s.snapshot->>'assignmentVersion')::bigint AS assignment_version,s.snapshot->>'updatedAt' AS updated_at,"+status+" AS feedback_status,g.version AS feedback_version,g.submission_version AS feedback_submission_version,"+marker+" AS marker_state,gr.version AS retraction_version,rr.version AS request_version,rr.submission_version AS requested_submission_version,"+request+" AS request_state,s.assignment_id,a.snapshot->>'title' AS assignment_title,a.state AS assignment_state,st.state AS study_state FROM assignment_submission s JOIN study_assignment a ON a.assignment_id=s.assignment_id AND a.study_id=s.study_id AND a.group_id=s.group_id AND a.space_id=s.space_id JOIN group_study st ON st.study_id=s.study_id AND st.group_id=s.group_id AND st.space_id=s.space_id LEFT JOIN submission_feedback g ON g.submission_id=s.submission_id AND g.assignment_id=s.assignment_id AND g.study_id=s.study_id AND g.group_id=s.group_id AND g.space_id=s.space_id AND g.author_id=s.author_id LEFT JOIN feedback_retraction gr ON gr.feedback_id=g.feedback_id AND gr.feedback_version=g.version LEFT JOIN resubmission_request rr ON rr.submission_id=s.submission_id AND rr.assignment_id=s.assignment_id AND rr.study_id=s.study_id AND rr.group_id=s.group_id AND rr.space_id=s.space_id AND rr.author_id=s.author_id WHERE s.group_id=? AND s.space_id=? AND s.study_id=?) SELECT rows.*,(feedback_status<>'CURRENT') AS needs_feedback FROM rows WHERE ("+condition+")"+(after==null?"":" AND submission_id>?")+" ORDER BY submission_id LIMIT ?";
  var args=new ArrayList<Object>(List.of(group,space,study));if(after!=null)args.add(after);args.add(limit+1);
  var rows=sql.query(query,(rs,n)->new Row(rs.getObject("submission_id",UUID.class),rs.getObject("author_id",UUID.class),rs.getLong("version"),rs.getLong("assignment_version"),rs.getString("updated_at"),rs.getString("feedback_status"),rs.getObject("feedback_version",Long.class),rs.getObject("feedback_submission_version",Long.class),rs.getString("marker_state"),rs.getObject("retraction_version",Long.class),rs.getBoolean("needs_feedback"),rs.getObject("request_version",Long.class),rs.getString("request_state"),rs.getObject("requested_submission_version",Long.class),rs.getObject("assignment_id",UUID.class),rs.getString("assignment_title"),rs.getString("assignment_state"),rs.getString("study_state")),args.toArray());var items=List.copyOf(rows.subList(0,Math.min(limit,rows.size())));return new Page(items,rows.size()>limit?items.getLast().submissionId():null);
 }
}
